using System; using System.IO; using System.Windows.Forms; using MySql.Data.MySqlClient; using System.Text; namespace MCPMS.Forms.Reports { public partial class ReportsForm:Form { private MCPMS.Classes.UserModel _user; public ReportsForm(MCPMS.Classes.UserModel user){ _user=user; InitializeComponent(); } private void btnExport_Click(object sender, EventArgs e){ try{ var from = dtFrom.Value; var to = dtTo.Value; var sb = new StringBuilder(); sb.AppendLine("AppointmentId,PatientId,ProviderId,AppointmentDate,Reason,Status"); using(var conn = MCPMS.Classes.DbConnection.GetConnection()){ conn.Open(); using(var cmd = conn.CreateCommand()){ cmd.CommandText = "SELECT AppointmentId, PatientId, ProviderId, AppointmentDate, Reason, Status FROM Appointments WHERE AppointmentDate BETWEEN @f AND @t"; cmd.Parameters.AddWithValue("@f", from); cmd.Parameters.AddWithValue("@t", to); using(var r = cmd.ExecuteReader()){ while(r.Read()){ sb.AppendLine($"{r[0]},{r[1]},{r[2]},{r[3]},{r[4]},{r[5]}"); } } } } var path = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "reports_export.csv"); File.WriteAllText(path, sb.ToString()); MessageBox.Show("Exported to " + path); } catch(Exception ex){ MessageBox.Show("Export failed: " + ex.Message); } } } }